head.script:
scwin.fr_SecuGrpId;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.gBzProcsNo;
scwin.gAcptNo;
scwin.gListProcsStatCd;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.gAcptNo;
scwin.gViewerStat; // 처리시 뷰어=P,  조회시 뷰어=R
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top_1);
        $c.cm.PanelToGroupBox(panel_Top_2);
        MaxTab_01.setSelectedTabIndex(1);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDATE.setValue($c.ut.cGetMinusDate2(vCurDate, 90));
        edt_EDATE.setValue(vCurDate);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05810.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05810.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05810.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadError
 * @description dts_List_2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
