    try {
        await $c.win.alert(dts_List_2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05810.dts_List_2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_1.setValue("총 " + dts_List_1.getRowCount() + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05810.dts_List_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadCompleted
 * @description dts_List_2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_2.setValue("총 " + dts_List_2.getRowCount() + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05810.dts_List_2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_1_OnDblClick
 * @description grd_List_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_1_OnDblClick = async function(row, colid) {
    try {
        scwin.setContnId(row);
        await $c.stf.openDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05810.grd_List_1_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List_2_OnDblClick
 * @description grd_List_2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_2_OnDblClick = async function(row, colid) {
    try {
        if (colid === "LIST_BZ_APPL_DDTM") {
            await scwin.openRecvDetail(row, colid);
        } else {
            await scwin.openDetail(row);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05810.grd_List_2_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_1_onclick
 * @description btn_Search_1 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_1_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05810.btn_Search_1_onclick" });
