/**
 * @method
 * @name img_Excel_2_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Excel_2_onclick = function() {
    try {
        if (dts_List_2.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF05810.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewOffice(grd_List_2, "세그먼트관리 목록", "", 8, 0);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05810.img_Excel_2_onclick" });
    }
};

/**
 * @method
 * @name img_SDATE_onclick
 * @description img_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05810.img_SDATE_onclick" });
    }
};

/**
 * @method
 * @name img_EDATE_onclick
 * @description img_EDATE 클릭 이벤트
 * @returns {void}
