        popUpCalendar2(edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05810.img_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05810.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05810.txb_ISUR_CD_onblur" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/SegmentChange.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        let pSEG_TP_CD = cmb_SEG_TP_CD.getValue();
        if (cmb_SEG_TP_CD.getValue() === "") {
            pSEG_TP_CD = "A";
        }
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&SEG_TP_CD=" + pSEG_TP_CD;
        url += "&PROCS_STAT_CD=" + rdo_PROCS_STAT_CD.getValue();
        url += "&SDATE=" + edt_SDATE.getValue();
        url += "&EDATE=" + edt_EDATE.getValue();
        url += "&FINAL_YN=" + final_YN.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/SegmentChange.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = txb_COM_NM.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD !== '2') {
            await $c.win.alert("[소속부변경]업무는 코스닥회사만 해당합니다. 회사을 다시 선택바랍니다");
        }
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    const formCd = dts_List_2.getCellData(row, "FORM_CD");
    let segChgTpCd = dts_List_2.getCellData(row, "SEG_CHG_TP_CD");
    let acptNo = dts_List_2.getCellData(row, "ACPT_NO");
    if (segChgTpCd === "04") {
        // 신규상장 입력
        await $c.frame.CreateFrame("ULDSTF05814", "/lstproc/ULDSTF05814.gfm", "세그먼트 관리상세(신규상장)", 0, 0, 840, 330, "window", 0, 0, false);
    } else if (acptNo === "") {
        // 공시부입력
        await $c.frame.CreateFrame("ULDSTF05815", "/lstproc/ULDSTF05815.gfm", "세그먼트 관리상세(신규상장)", 0, 0, 840, 730, "window", 0, 0, false);
    } else {
        if (formCd === "72088") {
            await $c.frame.CreateFrame("ULDSTF05811", "/lstproc/ULDSTF05811.gfm", "세그먼트 관리상세(신규지정요건)", 0, 0, 840, 815, "window", 0, 0, false);
        } else if (formCd === "72089") {
            await $c.frame.CreateFrame("ULDSTF05812", "/lstproc/ULDSTF05812.gfm", "세그먼트 관리상세(정기유지요건)", 0, 0, 840, 815, "window", 0, 0, false);
        } else if (formCd === "72090") {
            await $c.frame.CreateFrame("ULDSTF05813", "/lstproc/ULDSTF05813.gfm", "세그먼트 관리상세(지정취소)", 0, 0, 840, 330, "window", 0, 0, false);
        }
    }
};

/**
 * @method
 * @name openRecvDetail
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openRecvDetail = async function(row, colid) {
    let segChgTpCd = dts_List_2.getCellData(row, "SEG_CHG_TP_CD");
    let acptNo = dts_List_2.getCellData(row, "ACPT_NO");
    if (segChgTpCd === "04") {
        await $c.win.alert("신규상장으로 지정된 항목은 공시내역이 없습니다.");
        return;
    }
    if (acptNo === "") {
        await $c.win.alert("공시부에서 입력한 항목은 공시내역이 없습니다.");
        return;
    }
    scwin.setContnId(row);
    await $c.stf.openDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (Number(obj) > 0) {
        // 그리드에서 선택시
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            scwin.gAcptNo = dts_List_1.getCellData(Number(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_1.getCellData(Number(obj), "FORM_CD");
            scwin.gFormVer = dts_List_1.getCellData(Number(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_1.getCellData(Number(obj), "ISUR_CD");
            scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

        } else {
            scwin.gAcptNo = dts_List_2.getCellData(Number(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_2.getCellData(Number(obj), "FORM_CD");
            scwin.gFormVer = dts_List_2.getCellData(Number(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_2.getCellData(Number(obj), "ISUR_CD");
            scwin.gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R

        }
    }
};
